     1→import { useState, useCallback, useMemo, useEffect } from "react";
     2→import type {
     3→  ActionFunctionArgs,
     4→  HeadersFunction,
     5→  LoaderFunctionArgs,
     6→} from "react-router";
     7→import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
     8→import { useAppBridge } from "@shopify/app-bridge-react";
     9→import { authenticate } from "../shopify.server";
    10→import { boundary } from "@shopify/shopify-app-react-router/server";
    11→import db from "../db.server";
    12→import {
    13→  Page,
    14→  Layout,
    15→  Card,
    16→  BlockStack,
    17→  InlineStack,
    18→  Text,
    19→  Button,
    20→  TextField,
    21→  Select,
    22→  Modal,
    23→  EmptyState,
    24→  Divider,
    25→  Box,
    26→  Badge,
    27→  Tabs,
    28→  InlineGrid,
    29→  Banner,
    30→} from "@shopify/polaris";
    31→import { PlusIcon, DeleteIcon, ChevronUpIcon } from "@shopify/polaris-icons";
    32→
    33→const PAGE_SIZE = 10;
    34→const ADMIN_SHOP = "zip-code-checker.myshopify.com";
    35→const MAX_REQUESTS_PER_SHOP = 20;
    36→const MAX_DESCRIPTION_LENGTH = 2000;
    37→
    38→// ---------------------------------------------------------------------------
    39→// Types
    40→// ---------------------------------------------------------------------------
    41→
    42→type FeatureRequestRecord = {
    43→  id: string;
    44→  title: string;
    45→  description: string;
    46→  category: string;
    47→  status: string;
    48→  shop: string;
    49→  votesCount: number;
    50→  createdAt: string | Date;
    51→  updatedAt: string | Date;
    52→};
    53→
    54→type VoteResult = {
    55→  success: true;
    56→  intent: "vote";
    57→  featureId: string;
    58→  newCount: number;
    59→  voted: boolean;
    60→};
    61→type SubmitResult = { success: true; intent: "submit" };
    62→type DeleteResult = { success: true; intent: "delete" };
    63→type StatusResult = { success: true; intent: "update-status" };
    64→type ErrorResult = { error: string };
    65→
    66→type ActionResult =
    67→  | VoteResult
    68→  | SubmitResult
    69→  | DeleteResult
    70→  | StatusResult
    71→  | ErrorResult;
    72→
    73→// ---------------------------------------------------------------------------
    74→// Constants
    75→// ---------------------------------------------------------------------------
    76→
    77→const VALID_CATEGORIES = new Set([
    78→  "General",
    79→  "UI & Design",
    80→  "Data & Export",
    81→  "API & Integration",
    82→  "Performance",
    83→  "Billing",
    84→]);
    85→
    86→const VALID_STATUSES = new Set([
    87→  "under_review",
    88→  "planned",
    89→  "in_progress",
    90→  "done",
    91→  "shipped",
    92→]);
    93→
    94→const STATUS_LABELS: Record<string, string> = {
    95→  under_review: "Under Review",
    96→  planned: "Planned",
    97→  in_progress: "In Progress",
    98→  done: "Done",
    99→  shipped: "Shipped",
   100→};
   101→
   102→type BadgeTone =
   103→  | "attention"
   104→  | "info"
   105→  | "warning"
   106→  | "success"
   107→  | "critical"
   108→  | undefined;
   109→
   110→const STATUS_TONES: Record<string, BadgeTone> = {
   111→  under_review: "attention",
   112→  planned: "info",
   113→  in_progress: "warning",
   114→  done: "success",
   115→  shipped: "success",
   116→};
   117→
   118→const CATEGORY_OPTIONS = [
   119→  { label: "General", value: "General" },
   120→  { label: "UI & Design", value: "UI & Design" },
   121→  { label: "Data & Export", value: "Data & Export" },
   122→  { label: "API & Integration", value: "API & Integration" },
   123→  { label: "Performance", value: "Performance" },
   124→  { label: "Billing", value: "Billing" },
   125→];
   126→
   127→const STATUS_OPTIONS = [
   128→  { label: "Under Review", value: "under_review" },
   129→  { label: "Planned", value: "planned" },
   130→  { label: "In Progress", value: "in_progress" },
   131→  { label: "Done", value: "done" },
   132→  { label: "Shipped", value: "shipped" },
   133→];
   134→
   135→const TAB_FILTERS = [
   136→  "all",
   137→  "under_review",
   138→  "planned",
   139→  "in_progress",
   140→  "done",
   141→] as const;
   142→type TabFilter = (typeof TAB_FILTERS)[number];
   143→
   144→const SORT_OPTIONS = [
   145→  { label: "Most Voted", value: "votes" },
   146→  { label: "Newest", value: "newest" },
   147→  { label: "Oldest", value: "oldest" },
   148→];
   149→
   150→function formatDate(d: string | Date): string {
   151→  return new Date(d).toLocaleDateString("en-US", {
   152→    month: "short",
   153→    day: "numeric",
   154→    year: "numeric",
   155→  });
   156→}
   157→
   158→function truncateText(text: string, maxChars: number): string {
   159→  if (text.length <= maxChars) return text;
   160→  return text.slice(0, maxChars).trimEnd() + "\u2026";
   161→}
   162→
   163→// ---------------------------------------------------------------------------
   164→// Loader
   165→// ---------------------------------------------------------------------------
   166→
   167→export const loader = async ({ request }: LoaderFunctionArgs) => {
   168→  const { session } = await authenticate.admin(request);
   169→  const shop = session.shop;
   170→
   171→  const [features, myVotes] = await Promise.all([
   172→    db.featureRequest.findMany({
   173→      orderBy: { votesCount: "desc" },
   174→      take: 500,
   175→    }),
   176→    db.featureVote.findMany({
   177→      where: { shop },
   178→      select: { featureRequestId: true },
   179→    }),
   180→  ]);
   181→
   182→  const votedIds = myVotes.map((v) => v.featureRequestId);
   183→
   184→  const stats = {
   185→    total: features.length,
   186→    under_review: features.filter((f) => f.status === "under_review").length,
   187→    planned: features.filter((f) => f.status === "planned").length,
   188→    in_progress: features.filter((f) => f.status === "in_progress").length,
   189→    done: features.filter(
   190→      (f) => f.status === "done" || f.status === "shipped",
   191→    ).length,
   192→  };
   193→
   194→  const isAdmin = shop === ADMIN_SHOP;
   195→
   196→  return { features, votedIds, shop, stats, isAdmin };
   197→};
   198→
   199→// ---------------------------------------------------------------------------
   200→// Action
   201→// ---------------------------------------------------------------------------
   202→
   203→export const action = async ({
   204→  request,
   205→}: ActionFunctionArgs): Promise<ActionResult> => {
   206→  const { session } = await authenticate.admin(request);
   207→  const shop = session.shop;
   208→  const isAdmin = shop === ADMIN_SHOP;
   209→  const formData = await request.formData();
   210→  const intent = String(formData.get("intent") ?? "");
   211→
   212→  try {
   213→    switch (intent) {
   214→      case "submit": {
   215→        const title = String(formData.get("title") ?? "").trim();
   216→        const description = String(formData.get("description") ?? "").trim();
   217→        const rawCategory = String(formData.get("category") ?? "General").trim();
   218→        const category = VALID_CATEGORIES.has(rawCategory) ? rawCategory : "General";
   219→
   220→        if (!title || !description) {
   221→          return { error: "Title and description are required." };
   222→        }
   223→        if (title.length > 150) {
   224→          return { error: "Title must be 150 characters or fewer." };
   225→        }
   226→        if (description.length > MAX_DESCRIPTION_LENGTH) {
   227→          return { error: `Description must be ${MAX_DESCRIPTION_LENGTH} characters or fewer.` };
   228→        }
   229→
   230→        // Per-shop submission limit
   231→        const existingCount = await db.featureRequest.count({ where: { shop } });
   232→        if (existingCount >= MAX_REQUESTS_PER_SHOP) {
   233→          return { error: `You can submit up to ${MAX_REQUESTS_PER_SHOP} feature requests. Delete an existing one to submit a new one.` };
   234→        }
   235→
   236→        await db.featureRequest.create({
   237→          data: { title, description, category, shop },
   238→        });
   239→
   240→        return { success: true, intent: "submit" };
   241→      }
   242→
   243→      case "vote": {
   244→        const featureId = String(formData.get("featureId") ?? "").trim();
   245→        if (!featureId) return { error: "Feature ID is required." };
   246→
   247→        const feature = await db.featureRequest.findUnique({
   248→          where: { id: featureId },
   249→        });
   250→        if (!feature) return { error: "Feature request not found." };
   251→
   252→        const existing = await db.featureVote.findUnique({
   253→          where: {
   254→            featureRequestId_shop: { featureRequestId: featureId, shop },
   255→          },
   256→        });
   257→
   258→        let voted: boolean;
   259→
   260→        if (existing) {
   261→          await db.featureVote.delete({ where: { id: existing.id } });
   262→          // Atomic decrement
   263→          const updated = await db.featureRequest.update({
   264→            where: { id: featureId },
   265→            data: { votesCount: { decrement: 1 } },
   266→          });
   267→          // Ensure count doesn't go below 0
   268→          if (updated.votesCount < 0) {
   269→            await db.featureRequest.update({
   270→              where: { id: featureId },
   271→              data: { votesCount: 0 },
   272→            });
   273→          }
   274→          voted = false;
   275→          const finalCount = Math.max(0, updated.votesCount);
   276→          return { success: true, intent: "vote", featureId, newCount: finalCount, voted };
   277→        } else {
   278→          await db.featureVote.create({
   279→            data: { featureRequestId: featureId, shop },
   280→          });
   281→          // Atomic increment
   282→          const updated = await db.featureRequest.update({
   283→            where: { id: featureId },
   284→            data: { votesCount: { increment: 1 } },
   285→          });
   286→          voted = true;
   287→          return { success: true, intent: "vote", featureId, newCount: updated.votesCount, voted };
   288→        }
   289→      }
   290→
   291→      case "delete": {
   292→        const deleteId = String(formData.get("id") ?? "").trim();
   293→        if (!deleteId) return { error: "Feature ID is required." };
   294→
   295→        const toDelete = await db.featureRequest.findUnique({
   296→          where: { id: deleteId },
   297→        });
   298→        if (!toDelete) return { error: "Feature request not found." };
   299→
   300→        // Admin can delete any, regular users only their own
   301→        if (!isAdmin && toDelete.shop !== shop) {
   302→          return { error: "You can only delete your own feature requests." };
   303→        }
   304→
   305→        await db.featureRequest.delete({ where: { id: deleteId } });
   306→        return { success: true, intent: "delete" };
   307→      }
   308→
   309→      case "update-status": {
   310→        if (!isAdmin) {
   311→          return { error: "Only the app admin can change request statuses." };
   312→        }
   313→
   314→        const statusId = String(formData.get("id") ?? "").trim();
   315→        const newStatus = String(formData.get("status") ?? "").trim();
   316→
   317→        if (!statusId) return { error: "Feature ID is required." };
   318→        if (!VALID_STATUSES.has(newStatus)) {
   319→          return { error: "Invalid status value." };
   320→        }
   321→
   322→        const toUpdate = await db.featureRequest.findUnique({
   323→          where: { id: statusId },
   324→        });
   325→        if (!toUpdate) return { error: "Feature request not found." };
   326→
   327→        await db.featureRequest.update({
   328→          where: { id: statusId },
   329→          data: { status: newStatus },
   330→        });
   331→
   332→        return { success: true, intent: "update-status" };
   333→      }
   334→
   335→      default:
   336→        return { error: "Unknown action." };
   337→    }
   338→  } catch (err) {
   339→    const message =
   340→      err instanceof Error ? err.message : "An unexpected error occurred.";
   341→    return { error: message };
   342→  }
   343→};
   344→
   345→// ---------------------------------------------------------------------------
   346→// Component
   347→// ---------------------------------------------------------------------------
   348→
   349→export default function FeatureRequestsPage() {
   350→  const {
   351→    features: rawFeatures,
   352→    votedIds: initialVotedIds,
   353→    shop,
   354→    stats,
   355→    isAdmin,
   356→  } = useLoaderData<typeof loader>();
   357→
   358→  // Separate fetchers for independent actions (Fix #6)
   359→  const voteFetcher = useFetcher<typeof action>();
   360→  const deleteFetcher = useFetcher<typeof action>();
   361→  const submitFetcher = useFetcher<typeof action>();
   362→  const statusFetcher = useFetcher<typeof action>();
   363→
   364→  const shopify = useAppBridge();
   365→  const navigate = useNavigate();
   366→
   367→  // ------------------------------------------------------------------
   368→  // Local state — optimistic votes
   369→  // ------------------------------------------------------------------
   370→  const [optimisticVotes, setOptimisticVotes] = useState<
   371→    Map<string, { count: number; voted: boolean }>
   372→  >(() => new Map());
   373→  const [votedIds, setVotedIds] = useState<Set<string>>(
   374→    () => new Set(initialVotedIds),
   375→  );
   376→
   377→  // Per-card loading indicators
   378→  const [pendingVoteId, setPendingVoteId] = useState<string | null>(null);
   379→  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
   380→
   381→  // ------------------------------------------------------------------
   382→  // UI state
   383→  // ------------------------------------------------------------------
   384→  const [selectedTab, setSelectedTab] = useState(0);
   385→  const [sortValue, setSortValue] = useState("votes");
   386→  const [currentPage, setCurrentPage] = useState(1);
   387→  const [modalOpen, setModalOpen] = useState(false);
   388→  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
   389→  const [modalError, setModalError] = useState<string | null>(null);
   390→
   391→  // Form state
   392→  const [newTitle, setNewTitle] = useState("");
   393→  const [newDescription, setNewDescription] = useState("");
   394→  const [newCategory, setNewCategory] = useState("General");
   395→
   396→  // ------------------------------------------------------------------
   397→  // Resolve optimistic state into features list
   398→  // ------------------------------------------------------------------
   399→  const features = useMemo<FeatureRequestRecord[]>(() => {
   400→    return (rawFeatures as FeatureRequestRecord[]).map((f) => {
   401→      const opt = optimisticVotes.get(f.id);
   402→      if (opt) return { ...f, votesCount: opt.count };
   403→      return f;
   404→    });
   405→  }, [rawFeatures, optimisticVotes]);
   406→
   407→  // ------------------------------------------------------------------
   408→  // Handle vote fetcher responses
   409→  // ------------------------------------------------------------------
   410→  useEffect(() => {
   411→    if (voteFetcher.state !== "idle" || !voteFetcher.data) return;
   412→    const data = voteFetcher.data;
   413→
   414→    if ("error" in data) {
   415→      shopify.toast.show(data.error, { isError: true });
   416→      setPendingVoteId(null);
   417→      return;
   418→    }
   419→
   420→    if ("success" in data && data.success && data.intent === "vote") {
   421→      const voteData = data as VoteResult;
   422→      setOptimisticVotes((prev) => {
   423→        const next = new Map(prev);
   424→        next.set(voteData.featureId, {
   425→          count: voteData.newCount,
   426→          voted: voteData.voted,
   427→        });
   428→        return next;
   429→      });
   430→      setVotedIds((prev) => {
   431→        const next = new Set(prev);
   432→        if (voteData.voted) next.add(voteData.featureId);
   433→        else next.delete(voteData.featureId);
   434→        return next;
   435→      });
   436→      setPendingVoteId(null);
   437→    }
   438→  }, [voteFetcher.state, voteFetcher.data, shopify]);
   439→
   440→  // ------------------------------------------------------------------
   441→  // Handle delete fetcher responses
   442→  // ------------------------------------------------------------------
   443→  useEffect(() => {
   444→    if (deleteFetcher.state !== "idle" || !deleteFetcher.data) return;
   445→    const data = deleteFetcher.data;
   446→
   447→    if ("error" in data) {
   448→      shopify.toast.show(data.error, { isError: true });
   449→      setPendingDeleteId(null);
   450→      return;
   451→    }
   452→
   453→    if ("success" in data && data.success && data.intent === "delete") {
   454→      shopify.toast.show("Feature request deleted.");
   455→      setPendingDeleteId(null);
   456→    }
   457→  }, [deleteFetcher.state, deleteFetcher.data, shopify]);
   458→
   459→  // ------------------------------------------------------------------
   460→  // Handle submit fetcher responses
   461→  // ------------------------------------------------------------------
   462→  useEffect(() => {
   463→    if (submitFetcher.state !== "idle" || !submitFetcher.data) return;
   464→    const data = submitFetcher.data;
   465→
   466→    if ("error" in data) {
   467→      setModalError(data.error);
   468→      return;
   469→    }
   470→
   471→    if ("success" in data && data.success && data.intent === "submit") {
   472→      shopify.toast.show("Feature request submitted! Thank you.");
   473→      setModalOpen(false);
   474→      setNewTitle("");
   475→      setNewDescription("");
   476→      setNewCategory("General");
   477→      setModalError(null);
   478→    }
   479→  }, [submitFetcher.state, submitFetcher.data, shopify]);
   480→
   481→  // ------------------------------------------------------------------
   482→  // Handle status fetcher responses
   483→  // ------------------------------------------------------------------
   484→  useEffect(() => {
   485→    if (statusFetcher.state !== "idle" || !statusFetcher.data) return;
   486→    const data = statusFetcher.data;
   487→
   488→    if ("error" in data) {
   489→      shopify.toast.show(data.error, { isError: true });
   490→      return;
   491→    }
   492→
   493→    if ("success" in data && data.success && data.intent === "update-status") {
   494→      shopify.toast.show("Status updated.");
   495→    }
   496→  }, [statusFetcher.state, statusFetcher.data, shopify]);
   497→
   498→  // ------------------------------------------------------------------
   499→  // Filter + sort
   500→  // ------------------------------------------------------------------
   501→  const tabFilter: TabFilter = TAB_FILTERS[selectedTab] ?? "all";
   502→
   503→  const filteredFeatures = useMemo(() => {
   504→    let list = features;
   505→
   506→    if (tabFilter !== "all") {
   507→      if (tabFilter === "done") {
   508→        list = list.filter(
   509→          (f) => f.status === "done" || f.status === "shipped",
   510→        );
   511→      } else {
   512→        list = list.filter((f) => f.status === tabFilter);
   513→      }
   514→    }
   515→
   516→    return [...list].sort((a, b) => {
   517→      if (sortValue === "votes") return b.votesCount - a.votesCount;
   518→      if (sortValue === "newest")
   519→        return (
   520→          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
   521→        );
   522→      if (sortValue === "oldest")
   523→        return (
   524→          new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
   525→        );
   526→      return 0;
   527→    });
   528→  }, [features, tabFilter, sortValue]);
   529→
   530→  const totalPages = Math.max(
   531→    1,
   532→    Math.ceil(filteredFeatures.length / PAGE_SIZE),
   533→  );
   534→  const paginatedFeatures = useMemo(() => {
   535→    const start = (currentPage - 1) * PAGE_SIZE;
   536→    return filteredFeatures.slice(start, start + PAGE_SIZE);
   537→  }, [filteredFeatures, currentPage]);
   538→
   539→  // ------------------------------------------------------------------
   540→  // Handlers
   541→  // ------------------------------------------------------------------
   542→  const handleTabChange = useCallback((tabIndex: number) => {
   543→    setSelectedTab(tabIndex);
   544→    setCurrentPage(1);
   545→  }, []);
   546→
   547→  const handleSortChange = useCallback((val: string) => {
   548→    setSortValue(val);
   549→    setCurrentPage(1);
   550→  }, []);
   551→
   552→  const handleVote = useCallback(
   553→    (featureId: string) => {
   554→      const feature = features.find((f) => f.id === featureId);
   555→      if (!feature) return;
   556→
   557→      const currentlyVoted = votedIds.has(featureId);
   558→      const currentCount =
   559→        optimisticVotes.get(featureId)?.count ?? feature.votesCount;
   560→
   561→      // Optimistic update
   562→      setOptimisticVotes((prev) => {
   563→        const next = new Map(prev);
   564→        next.set(featureId, {
   565→          count: currentlyVoted
   566→            ? Math.max(0, currentCount - 1)
   567→            : currentCount + 1,
   568→          voted: !currentlyVoted,
   569→        });
   570→        return next;
   571→      });
   572→      setVotedIds((prev) => {
   573→        const next = new Set(prev);
   574→        if (currentlyVoted) next.delete(featureId);
   575→        else next.add(featureId);
   576→        return next;
   577→      });
   578→
   579→      setPendingVoteId(featureId);
   580→
   581→      const fd = new FormData();
   582→      fd.set("intent", "vote");
   583→      fd.set("featureId", featureId);
   584→      voteFetcher.submit(fd, { method: "POST" });
   585→    },
   586→    [features, votedIds, optimisticVotes, voteFetcher],
   587→  );
   588→
   589→  const handleDelete = useCallback(
   590→    (id: string) => {
   591→      setPendingDeleteId(id);
   592→
   593→      const fd = new FormData();
   594→      fd.set("intent", "delete");
   595→      fd.set("id", id);
   596→      deleteFetcher.submit(fd, { method: "POST" });
   597→    },
   598→    [deleteFetcher],
   599→  );
   600→
   601→  const handleSubmitFeature = useCallback(() => {
   602→    if (!newTitle.trim() || !newDescription.trim()) {
   603→      setModalError("Title and description are required.");
   604→      return;
   605→    }
   606→    if (newDescription.trim().length > MAX_DESCRIPTION_LENGTH) {
   607→      setModalError(`Description must be ${MAX_DESCRIPTION_LENGTH} characters or fewer.`);
   608→      return;
   609→    }
   610→    setModalError(null);
   611→
   612→    const fd = new FormData();
   613→    fd.set("intent", "submit");
   614→    fd.set("title", newTitle.trim());
   615→    fd.set("description", newDescription.trim());
   616→    fd.set("category", newCategory);
   617→    submitFetcher.submit(fd, { method: "POST" });
   618→  }, [newTitle, newDescription, newCategory, submitFetcher]);
   619→
   620→  const handleStatusChange = useCallback(
   621→    (id: string, newStatus: string) => {
   622→      const fd = new FormData();
   623→      fd.set("intent", "update-status");
   624→      fd.set("id", id);
   625→      fd.set("status", newStatus);
   626→      statusFetcher.submit(fd, { method: "POST" });
   627→    },
   628→    [statusFetcher],
   629→  );
   630→
   631→  const handleToggleExpand = useCallback((id: string) => {
   632→    setExpandedIds((prev) => {
   633→      const next = new Set(prev);
   634→      if (next.has(id)) next.delete(id);
